def has_dup_slow(items):
    steps = 0
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            steps += 1
            if items[i] == items[j]:
                return True, steps
    return False, steps


def has_dup_fast(items):
    seen = set()
    steps = 0
    for x in items:
        steps += 1
        if x in seen:
            return True, steps
        seen.add(x)
    return False, steps

from functools import lru_cache

calls = 0


def fib_slow(n):
    global calls
    calls += 1
    return n if n < 2 else fib_slow(n - 1) + fib_slow(n - 2)


@lru_cache(maxsize=None)
def fib_fast(n):
    global calls
    calls += 1
    return n if n < 2 else fib_fast(n - 1) + fib_fast(n - 2)

SENSITIVE = {"password", "token", "card"}


def safe(data):
    return {k: ("***" if k in SENSITIVE else v) for k, v in data.items()}
